def diag(kind,title,nodes,refs,caption='Relations structurales et niveaux de preuve ; les différences ne constituent pas une échelle de puissance humaine.'):
 return dict(kind=kind,title=title,nodes=[dict(label=l,detail=t) for l,t in nodes],caption=caption,sourceIds=refs.split())
