count=0
for p in root.glob('cannabinoids-*.json'):
 b=json.loads(p.read_text(encoding='utf-8'))
 for s in b['sources']:
  if s.get('author'):s['author']=s['author'].replace('T?mas F. Freund','Tamás F. Freund').replace('T?mas','Tamás')
 for a in b['articles']:
  key=a['id'].removeprefix('record-cannabinoid-')
  if key not in cfg:continue
  kind,title,nodes,refs=cfg[key]
  a['patch']['diagram']=diag(kind,title,nodes,refs)
  if key in identity:a['patch']['sections'][0]['paragraphs']=[identity[key]]
  if key in maps:
   for sec,refs2 in zip(a['patch']['sections'],maps[key]):sec['sourceIds']=refs2.split()
  a['visual']=dict(status='verified',notes='Diagramme original spécifique ajouté et contrôlé : relations structurales, transformations ou résultats expérimentaux nommés et limites explicites. Schéma conceptuel, pas dessin atomique ; aucune photo scientifique indispensable ni ancienne vignette certifiée comme observation.')
  a['findings'].append('Reprise après contrôle du coordinateur : diagramme spécifique effectivement inclus ; identité développée si fragmentaire et références distribuées selon les assertions des sections.')
  assert set(a['patch']['diagram']['sourceIds'])<=set(a['patch']['sourceIds']),a['id']
  count+=1
 p.write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
assert count==24,count
print('24 diagrammes ajoutés ; 12 identités développées ; références par section précisées ; Tamás corrigé.')
